-- Hochschulen (Deutschland, Österreich, Schweiz) für Uni-Suche, Uni-Mail-Erkennung, später Mensa und Semesterdaten
create table public.hochschule (
  id text primary key,                 -- Wikidata-ID (z. B. Q273263)
  name text not null,
  kurzname text,
  ort text,
  land text not null check (land in ('DE', 'AT', 'CH')),
  art text not null default 'sonstige' check (art in ('uni', 'fh', 'sonstige')),
  website text,
  domains text[] not null default '{}'
);
alter table public.hochschule enable row level security;
create policy "Hochschulen sind für alle lesbar" on public.hochschule for select to anon, authenticated using (true);
create index hochschule_domains_idx on public.hochschule using gin (domains);

-- Gewählte Hochschule im Profil (oder freie Angabe, wenn sie fehlt)
alter table public.settings
  add column hochschule_id text references public.hochschule (id) on delete set null,
  add column hochschule_frei text check (char_length(hochschule_frei) <= 160);

-- Bestätigte Uni-Mail. Lesen nur die eigene Zeile; schreiben nur der Server (Secret Key),
-- damit niemand sich selbst als bestätigt eintragen kann.
create table public.uni_verifizierung (
  user_id uuid primary key references auth.users (id) on delete cascade,
  email text not null,
  hochschule_id text references public.hochschule (id) on delete set null,
  code_hash text,
  code_laeuft_ab timestamptz,
  versuche int not null default 0,
  gesendet_am timestamptz[] not null default '{}',
  bestaetigt_am timestamptz,
  gueltig_bis timestamptz,
  erstellt_am timestamptz not null default now()
);
alter table public.uni_verifizierung enable row level security;
create policy "Eigene Uni-Verifizierung lesen" on public.uni_verifizierung for select to authenticated using ((select auth.uid()) = user_id);
-- Eine bestätigte Uni-Mail gehört genau einem Konto
create unique index uni_verifizierung_email_bestaetigt on public.uni_verifizierung (lower(email)) where bestaetigt_am is not null;

-- Daten: Wikidata (CC0), Domains ergänzt aus Hipo/university-domains-list (MIT). Stand 17.11.2026.
on conflict (id) do nothing;
